breach.segment:
// PostgreSQL engine marker: excludes MySQL / SQL Server instances that share these metrics
WHERE pg > 0 AND cpu_n > 0
// cpu/utilization is the fraction of reserved vCPUs in use
| EVAL cpu_avg_pct = ROUND(cpu_sum / cpu_n * 100.0, 1),
       cpu_peak_pct = ROUND(cpu_peak * 100.0, 1)
// Minimum samples: require ~5 minutes of data so a single late sample cannot trigger
| WHERE cpu_n >= 5
// Alert threshold: average CPU utilization (percent) over the rule window
| WHERE cpu_avg_pct >= 90
| KEEP database_id, cpu_avg_pct, cpu_peak_pct, cpu_n
| SORT cpu_avg_pct DESC
| LIMIT 100
